                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 2 <= ny < h - 1 and 1 <= nx < w - 1 and grid[ny][nx] != 8 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)
            block = [row[left:right + 1] for row in grid[top:bottom + 1]]
            if vertical:
                block = [list(row) for row in zip(*block)]
            objects.append((top, left, block))

    if vertical:
        objects.sort(key=lambda item: (item[1], item[0]))
    else:
        objects.sort(key=lambda item: (item[0], -item[1] if grid[0][-1] == 0 else item[1]))

    width = max(len(row) for _, _, block in objects for row in block)
    result = []
    for _, _, block in objects:
        for row in block:
            padding = width - len(row)
            left = padding // 2
            result.append([8] * left + row + [8] * (padding - left))
    return result
